{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Step 1: compute mutual reachability distances for all pairs
    edge_list = []
    for entry in distances:
        a, b, d = entry[0], entry[1], entry[2]
        mrd = max(core_distance[a], core_distance[b], d)
        # Canonicalize order so a < b lexicographically
        if a > b:
            a, b = b, a
        edge_list.append((mrd, a, b))

    # Sort edges by mutual reachability distance (Kruskal's)
    edge_list.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find helpers
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        root = x
        while parent[root] != root:
            root = parent[root]
        # Path compression
        while parent[x] != root:
            parent[x], x = root, parent[x]
        return root

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    # Step 2: build MST
    mst_edges = []
    for weight, a, b in edge_list:
        if union(a, b):
            mst_edges.append([a, b, weight])
        if len(mst_edges) == len(nodes) - 1:
            break

    return {"mst_edges": mst_edges}
